 public sealed class AdventureHUD:MonoBehaviour {
  PinPopGame game;RectTransform frame;GameObject modal,toolbar,homeButton;Text stock,pocket,resultNote;readonly System.Collections.Generic.Dictionary<Text,int> fontSizes=new System.Collections.Generic.Dictionary<Text,int>();readonly Text[] counts=new Text[4];float fontScale=-1;int seenAttempt=-1;bool showing,testing;float openedAt;Font font;
  public bool ModalVisible=>showing;
  public void Build(PinPopGame owner){game=owner;testing=Array.Exists(Environment.GetCommandLineArgs(),a=>a.EndsWith("-test"));font=Font.CreateDynamicFontFromOSFont(new[]{"Avenir Next","Arial"},18)??Resources.Load<Font>("PinPop-Regular");var canvas=new GameObject("Adventure interface",typeof(RectTransform),typeof(Canvas),typeof(GraphicRaycaster));canvas.layer=5;canvas.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceCamera;canvas.GetComponent<Canvas>().worldCamera=owner.Hud.UICamera;canvas.GetComponent<Canvas>().planeDistance=.8f;canvas.GetComponent<Canvas>().sortingOrder=40;frame=Rect("Adventure frame",canvas.transform,0,0,600,1000);frame.anchorMin=frame.anchorMax=new Vector2(.5f,.5f);frame.pivot=new Vector2(.5f,.5f);
   toolbar=Rect("Booster toolbar",frame,28,785,390,90).gameObject;for(int i=0;i<4;i++){int id=i;var b=Button(toolbar.transform,"BOOSTER_"+id, i*96,0,90,67,AdventureRules.Symbols[i]+"\n"+new[]{"RENK","GÖKKUŞ.","CEP","HAMLE"}[i],()=>ShowBooster(id),"466B7A");b.GetComponentInChildren<Text>().fontSize=14;counts[i]=Label(toolbar.transform,"Booster stock "+i,i*96,69,90,20,"",14,"FFF4D8");counts[i].alignment=TextAnchor.MiddleCenter;}
   stock=Label(toolbar.transform,"Booster inventory",0,69,345,18,"",11,"FFF4D8");pocket=Label(frame,"Pocket status",30,757,350,25,"",14,"FFF4D8");homeButton=Button(frame,"MAP_HOME",172,800,256,52,"BÖLÜM HARİTASI",ShowMap,"48758A").gameObject;
   resultNote=Label(frame,"Milestone reward summary",110,695,380,40,"",15,"F5D989");resultNote.alignment=TextAnchor.MiddleCenter;
  }
  void Update(){if(frame==null||game.Adventure==null)return;var view=game.GetComponent<HtmlReferenceHUD>();var r=view.AppRect;frame.anchoredPosition=new Vector2(r.center.x-Screen.width/2,r.center.y-Screen.height/2);frame.localScale=new Vector3(r.width/600,r.height/1000,1);
   bool clear=!game.Hud.SettingsVisible&&!game.Hud.ShopVisible&&!game.Hud.SwapShopVisible&&!game.Hud.HelpVisible&&!game.Transitioning;
   toolbar.SetActive(!game.InMenu&&!game.Finished&&clear&&!showing);homeButton.SetActive(false);pocket.gameObject.SetActive(!game.InMenu&&!game.Finished&&!showing&&clear&&game.Adventure.PocketColor>=0);
   stock.text="";for(int i=0;i<4;i++)counts[i].text="×"+game.Adventure.Data.stock[i];float scale=Mathf.Min(frame.localScale.x,frame.localScale.y);if(Mathf.Abs(fontScale-scale)>.001f){fontScale=scale;ResizeFonts();}pocket.text=game.Adventure.PocketColor<0?"":"CEP: "+Art.Names[game.Adventure.PocketColor]+" · iki eşini bekliyor";
   resultNote.gameObject.SetActive(game.Finished&&game.Won&&game.Adventure.LastChest>0&&!showing);resultNote.text="SANDIK +"+game.Adventure.LastChestCoins+" COIN · +1 "+(game.Adventure.LastChest>0?AdventureRules.Boosters[(game.Adventure.LastChest-1)%4]:"");
   if(showing&&Input.GetKeyDown(KeyCode.Escape)){Close();return;}
   if(!testing&&!game.InMenu&&!game.Transitioning&&!game.Busy&&!game.Finished&&clear&&!showing&&seenAttempt!=game.AttemptId){if(openedAt<=0)openedAt=Time.unscaledTime;if(Time.unscaledTime-openedAt>.7f){seenAttempt=game.AttemptId;openedAt=0;ShowNextLesson();}}
  }
  public void ShowNextLesson(){var text=game.Adventure.Lesson();if(string.IsNullOrEmpty(text))return;Open("YENİ BİR ŞEY AÇILDI",text);var color=Mathf.Max(0,PinPopLayouts.ColorCount(game.Level)-1);var icon=Image("Unlocked character",modal.transform,245,360,110,145,Color.white);icon.sprite=Resources.Load<Sprite>("PinIcons/pin-"+color);icon.preserveAspect=true;Button(modal.transform,"LESSON_OK",150,660,300,60,"ANLADIM",()=>{Close();ShowNextLesson();},"70935E");}
  void Open(string title,string body){if(showing)Close();game.CancelPull();Time.timeScale=0;showing=true;modal=Rect("Adventure modal",frame,0,0,600,1000).gameObject;Image("Modal shade",modal.transform,0,0,600,1000,new Color(.07f,.15f,.19f,.84f),true);Image("Adventure card border",modal.transform,28,98,544,804,Art.Hex("C8BC97"));Image("Adventure card",modal.transform,30,100,540,800,Art.Hex("304F62"),true);Label(modal.transform,"Eyebrow",70,130,460,25,"PINPOP · LUNAPARK MACERASI",12,"D8C595").alignment=TextAnchor.MiddleCenter;Label(modal.transform,"Modal title",60,170,480,60,title,27,"FFF0C9").alignment=TextAnchor.MiddleCenter;var text=Label(modal.transform,"Modal explanation",65,240,470,100,body,17,"E7EEE7");text.alignment=TextAnchor.MiddleCenter;Button(modal.transform,"ADVENTURE_CLOSE",500,112,52,48,"×",Close,"456C7F");StartCoroutine(Reveal(modal.transform));}
  public void Close(){if(modal!=null){foreach(var t in modal.GetComponentsInChildren<Text>(true))fontSizes.Remove(t);modal.SetActive(false);Destroy(modal);}modal=null;showing=false;if(!game.Finished)Time.timeScale=1;UnityEngine.EventSystems.EventSystem.current?.SetSelectedGameObject(null);}
  public void ShowMap(){if(PinPopSplash.Visible)return;if(game.Transitioning||game.RewardedVideo!=null&&game.RewardedVideo.Busy)return;DrawMap();}
  void DrawMap(float? offset=null,int? requestedFocus=null){int focus=requestedFocus??AdventureRules.ClampLevel(game.HighestLevel);if(!AdventureRules.CanVisitRegion(focus/AdventureRules.LevelsPerRegion,game.HighestLevel))return;Open("","");foreach(Transform child in modal.transform)if(child.name!="Modal shade")child.gameObject.SetActive(false);var map=modal.AddComponent<CarnivalMapView>();map.Build(game,focus,level=>{Close();game.Hud.PlayLevel(level);},checkpoint=>{float position=map.ScrollOffset;if(game.Adventure.ClaimChest(checkpoint)){DrawMap(position,focus);game.Hud.Toast("SANDIK AÇILDI · +"+game.Adventure.LastChestCoins+" COIN",2);}},Close,region=>DrawMap(null,AdventureRules.FocusForRegion(region,game.HighestLevel)));if(offset.HasValue)map.SetScrollOffset(offset.Value);}
  public void ShowBooster(int id){if(game.Busy||game.Finished||game.Transitioning||game.IsPulling)return;string[] descriptions={"Sıradaki topun rengini seç. Hamle harcamaz.\nMasada kalan renklerden birini seçebilirsin.","Bir sonraki top bütün renklere etki eder.\nDüşen dubalar kendi renkleriyle toplanır.","Bekleyen bir dubayı tek kişilik cebe taşı.\nAynı renkten iki duba gelince üçlü tamamlanır.","Mevcut masayı koruyarak üç hamle ekle.\nÖdüllü video hakkını tüketmez."};Open(AdventureRules.Boosters[id].ToUpper(),descriptions[id]+"\nEnvanter: "+game.Adventure.Data.stock[id]);
   if(id==0){for(int c=0;c<PinPopLayouts.ColorCount(game.Level);c++){int color=c;var b=Button(modal.transform,"COLOR_CHOICE_"+c,80+(c%4)*115,370+(c/4)*82,105,64,Art.Names[c],()=>{Close();if(game.Adventure.Use(id,color))game.PlayEntryChime();},ColorUtility.ToHtmlStringRGB(Art.Colors[c]));b.interactable=game.Adventure.Data.stock[id]>0&&game.Pins.Exists(p=>p!=null&&!p.Cleared&&p.ColorId==color);}}
   else if(id==2){int n=0;foreach(var item in game.MatchTray.Items){if(item.Matched||!item.Arrived)continue;int token=item.Id;var b=Button(modal.transform,"POCKET_CHOICE_"+token,70+(n%5)*94,370+(n/5)*100,84,84,"",()=>{Close();game.Adventure.Use(id,-1,token);},"466B7A");var icon=Image("Pocket figure",b.transform,12,3,60,76,Color.white);icon.sprite=Resources.Load<Sprite>("PinIcons/pin-"+item.Color);icon.preserveAspect=true;b.interactable=game.Adventure.PocketColor<0&&game.Adventure.Data.stock[id]>0;n++;}if(n==0||game.Adventure.PocketColor>=0)Label(modal.transform,"Pocket availability",65,410,470,70,n==0?"Önce tepsiye bir duba topla.":"Cep dolu; iki eşini toplayarak boşalt.",18,"F4E1B4").alignment=TextAnchor.MiddleCenter;}
   else Button(modal.transform,"BOOSTER_USE",140,400,320,65,"KULLAN",()=>{Close();game.Adventure.Use(id);},"70935E").interactable=game.Adventure.Data.stock[id]>0&&(id!=1||!game.Adventure.RainbowArmed);
   Button(modal.transform,"BOOSTER_BUY",110,610,380,65,"+1 AL · "+AdventureRules.Prices[id]+" COIN",()=>{if(game.Adventure.Buy(id)){ShowBooster(id);game.Hud.Toast("Envantere +1 "+AdventureRules.Boosters[id],2);}},"B08A43").interactable=game.Coins>=AdventureRules.Prices[id]&&game.Adventure.Data.stock[id]<999;Label(modal.transform,"Booster balance",110,690,380,40,"BAKİYE: "+game.Coins+" COIN",16,"F4E1B4").alignment=TextAnchor.MiddleCenter;
  }
  IEnumerator Reveal(Transform target){if(game.ReducedMotion)yield break;for(float t=0;t<.18f;t+=Time.unscaledDeltaTime){if(target==null)yield break;float a=Mathf.Clamp01(t/.18f);target.localScale=Vector3.one*(.96f+.04f*(1-Mathf.Pow(1-a,3)));yield return null;}if(target!=null)target.localScale=Vector3.one;}
  RectTransform Rect(string name,Transform parent,float x,float y,float w,float h){var o=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer));o.layer=5;var r=o.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
  Image Image(string name,Transform parent,float x,float y,float w,float h,Color color,bool raycast=false){var r=Rect(name,parent,x,y,w,h);var img=r.gameObject.AddComponent<Image>();img.color=color;img.raycastTarget=raycast;img.sprite=PanelSprite();img.type=UnityEngine.UI.Image.Type.Sliced;img.pixelsPerUnitMultiplier=.4f;return img;}
  Text Label(Transform parent,string name,float x,float y,float w,float h,string text,int size,string color){var t=Rect(name,parent,x,y,w,h).gameObject.AddComponent<Text>();t.font=font;t.fontSize=size;t.fontStyle=FontStyle.Bold;t.color=Art.Hex(color);t.text=text;t.alignment=TextAnchor.MiddleLeft;fontSizes[t]=size;t.fontSize=Mathf.Max(size,Mathf.CeilToInt(12/Mathf.Max(.1f,Mathf.Min(frame.localScale.x,frame.localScale.y))));t.raycastTarget=false;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;return t;}
  Button Button(Transform parent,string name,float x,float y,float w,float h,string text,UnityEngine.Events.UnityAction action,string color){var bg=Image(name,parent,x,y,w,h,Art.Hex(color),true);var button=bg.gameObject.AddComponent<Button>();button.targetGraphic=bg;button.onClick.AddListener(action);Label(bg.transform,name+" label",4,2,w-8,h-4,text,16,"FFF3DC").alignment=TextAnchor.MiddleCenter;return button;}
  void ResizeFonts(){foreach(var pair in fontSizes)if(pair.Key!=null)pair.Key.fontSize=Mathf.Max(pair.Value,Mathf.CeilToInt(12/Mathf.Max(.1f,fontScale)));}
  static Sprite panel;static Sprite PanelSprite(){if(panel!=null)return panel;var t=new Texture2D(32,32,TextureFormat.RGBA32,false);var pixels=new Color32[1024];for(int y=0;y<32;y++)for(int x=0;x<32;x++){float dx=Mathf.Max(6-x,Mathf.Max(0,x-25)),dy=Mathf.Max(6-y,Mathf.Max(0,y-25));pixels[y*32+x]=dx*dx+dy*dy<=36?Color.white:Color.clear;}t.SetPixels32(pixels);t.Apply();panel=Sprite.Create(t,new Rect(0,0,32,32),Vector2.one*.5f,100,0,SpriteMeshType.FullRect,Vector4.one*8);return panel;}
 }
